insert into public.projects (slug, title, summary, status, published_at, is_featured, sort_order, industry, client_name, content) values
('integration-crm-erp-concept','Passerelle d''intégration CRM ↔ ERP','Concept de passerelle de synchronisation bidirectionnelle avec résolution des conflits.','published', now(), false, 60, 'Intégration', 'Concept',
