insert into public.project_technologies (project_id, technology_id)
select p.id, t.id
from public.projects p
join lateral jsonb_array_elements_text(coalesce(p.content->'technologies','[]'::jsonb)) as tech(name) on true
join public.technologies t on t.name = tech.name
on conflict do nothing;

insert into public.service_technologies (service_id, technology_id)
select s.id, t.id
from public.services s
join lateral jsonb_array_elements_text(coalesce(s.content->'technologies','[]'::jsonb)) as tech(name) on true
join public.technologies t on t.name = tech.name
on conflict do nothing;

insert into public.faqs (question, answer, category, status, sort_order) values
('Que peut concrètement automatiser Zawena ?','Tout processus répétitif dont les étapes sont identifiables : traitement des demandes entrantes, synchronisation entre outils, extraction de documents, reporting, relances. Nous commençons toujours par cartographier le processus réel avant d''automatiser.','general','published',10),
('Combien coûte un agent IA ?','Le coût dépend du nombre de systèmes connectés, du niveau de contrôle exigé et du volume traité. Nous établissons un chiffrage après un cadrage court ; vous pouvez demander un devis pour obtenir une estimation adaptée à votre contexte.','pricing','published',20),
('Pouvez-vous intégrer l''IA à notre logiciel existant ?','Oui, dès qu''une API ou un accès base de données est disponible. Notre approche consiste à ajouter une couche d''intégration plutôt qu''à reconstruire votre système.','general','published',30),
('Travaillez-vous avec les PME ?','Oui. Nous cadrons le périmètre pour livrer un premier résultat utile rapidement, puis nous étendons selon les usages réellement constatés.','general','published',40),
('Quels systèmes pouvez-vous intégrer ?','CRM, ERP, outils de support, bases de données, services internes et APIs tierces. Nous vérifions la faisabilité pendant le cadrage, avant tout engagement.','general','published',50),
('Proposez-vous des audits de cybersécurité ?','Oui : audit d''architecture et d''accès, analyse de vulnérabilités et tests d''intrusion cadrés. Chaque constat est livré avec un niveau de gravité et une correction recommandée.','security','published',60),
('Comment démarre un projet ?','Par un échange de cadrage, suivi d''une proposition écrite décrivant périmètre, livrables, jalons et hypothèses. La réalisation ne commence qu''après validation.','process','published',70),
('Nos données sont-elles utilisées pour entraîner des modèles ?','Non. Nous privilégions des configurations excluant l''entraînement sur vos données et limitons strictement les informations transmises aux services externes.','security','published',80)
on conflict do nothing;
